namespace SHBMS.Helper;

public static class EntityIds
{
    // CHAR keys need application values; INT identity keys are generated by SQL Server.

    /// <summary>
    /// Generate the next formatted text ID from the existing keys.
    /// </summary>
    public static string Next(IEnumerable<string> ids, string prefix, int digits)
    {
        // Call this inside the write transaction when the generated ID will be saved.
        var numbers = ids.Where(id => id.StartsWith(prefix, StringComparison.OrdinalIgnoreCase))
            .Select(id => int.TryParse(id[prefix.Length..], out int n) ? n : 0);
        int next = numbers.DefaultIfEmpty().Max() + 1;
        if (next >= Math.Pow(10, digits))
            throw new InvalidOperationException($"No more IDs for {prefix}.");
        return prefix + next.ToString("D" + digits);
    }

    /// <summary>
    /// Trim optional text and save blank values as null.
    /// </summary>
    public static string? Optional(string? value)
        => string.IsNullOrWhiteSpace(value) ? null : value.Trim();
}
